for (const [state, command] of CASES) {
  const id = 'S' + createHash('sha256').update(JSON.stringify([state, command])).digest('hex').slice(0, 12)
  test('[' + ROW + '] [' + id + '] ' + eventLabel(state) + ' · ' + eventLabel(command), UNLIMITED, () =>
    check(toRuntime(state, STATE, 'state'), toRuntime(command, COMMAND, 'command')),
  )
}
test('[' + ROW + '] sampled ItemState×Msg pairs (fast-check)', UNLIMITED, async () => {
  let executed = 0
  await fc.assert(fc.asyncProperty(arbitraryOf(fc, STATE), arbitraryOf(fc, COMMAND), async (state, command) => { executed += 1; await check(state, command) }), { numRuns: 300, seed: 1145624762 })
  console.log(JSON.stringify({ fastCheck: { row: ROW, requested: 300, executed, seed: 1145624762 } }))
  assert.ok(executed >= 300, 'fast-check executed ' + executed + ' of 300 requested runs')
})
